package org.apache.commons.codec.binary;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Base64InputStream_read_TriageGen2Test {













    @Test
    public void testRead_Decode_NormalFlow() throws IOException {
        // "SGVsbG8=" is "Hello"
        byte[] input = "SGVsbG8=".getBytes();
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(input), false);
        byte[] b = new byte[10];

        // Initial call might trigger the !hasData() block
        int result = bis.read(b, 0, 5);
        // "Hello" is 5 bytes
        assertEquals(5, result);
        assertEquals('H', b[0]);
        assertEquals('o', b[4]);
    }








}

package org.apache.commons.codec.binary;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Base64InputStream_read_TriageGen2Test {















    @Test
    public void testRead_Encode_NormalFlow() throws IOException {
        byte[] input = "Hello".getBytes();
        Base64InputStream bis = new Base64InputStream(new ByteArrayInputStream(input), true);
        byte[] b = new byte[20];

        int result = bis.read(b, 0, 12); 
        // "Hello" encodes to "SGVsbG8=" (8 chars)
        // Note: exact result depends on internal buffer logic, but we test path coverage
        assert(result > 0);
    }






}

